const editorRef=useRef(null);
const editorTriggerRef=useRef(null);
useEffect(()=>{if(!showForm)return;editorTriggerRef.current=document.activeElement;const previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';editorRef.current?.querySelector('input,select,textarea')?.focus();const key=e=>{if(e.key==='Escape'){e.preventDefault();setShowForm(false);setForm({})}if(e.key==='Tab'){const controls=[...editorRef.current?.querySelectorAll('button,input,select,textarea,a[href]')||[]].filter(el=>!el.disabled&&el.getClientRects().length&&!el.closest('details:not([open])'));const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}};document.addEventListener('keydown',key);return()=>{document.body.style.overflow=previousOverflow;document.removeEventListener('keydown',key);(editorTriggerRef.current?.isConnected&&editorTriggerRef.current!==document.body?editorTriggerRef.current:[...document.querySelectorAll('.tabletoolbar button')].find(el=>el.textContent.includes('إضافة جديدة'))||document.querySelector('main header button'))?.focus?.()}},[showForm]);
const [expandedGroups,setExpandedGroups]=useState({});
