useEffect(()=>{const group=navigationGroups.find(g=>g.children?.includes(tab));if(group)setExpandedGroups(v=>({...v,[group.id]:true}));},[tab]);
function toggleGroup(id){if(sidebarCollapsed){setSidebarCollapsed(false);try{localStorage.setItem('clinic.sidebar.collapsed','false')}catch{}setExpandedGroups(v=>({...v,[id]:true}));}else setExpandedGroups(v=>({...v,[id]:!v[id]}));}
useEffect(()=>{try{setSidebarCollapsed(localStorage.getItem('clinic.sidebar.collapsed')==='true')}catch{}},[]);
function toggleSidebar(){setSidebarCollapsed(v=>{try{localStorage.setItem('clinic.sidebar.collapsed',String(!v))}catch{}return !v});}
const rows=records.tab===tab&&records.user===session?.user.id?records.rows:[];
const moduleFor=m=>operationPages[m]?.permissionModule||(m==='purchasing/invoices'?'finance':m.split('/')[0]);
const can=(m,a)=>m==='dashboard'?a==='view'&&!!session?.user:(m!=='clinical'||['view','export'].includes(a)||['doctor','physio','physio_lead'].includes(session?.user.role))&&(!operationPages[m]?.ownerOnly||session?.user.role==='owner')&&(m==='purchasing/policy'?session?.user.role==='owner':m==='purchasing/invoices'?session?.permissions.includes('finance.'+a):true)&&(!['reports/integrations','finance/policy'].includes(m)||session?.user.role==='owner')&&session?.permissions.includes(moduleFor(m)+'.'+a);
const navigationGroups=roleNavigation(session?.user.role,allNavigationGroups,can,labels);
const accessibleGroups=navigationGroups.filter(g=>g.children?.some(m=>can(m,'view')));
const allGroupsExpanded=!sidebarCollapsed&&accessibleGroups.length>0&&accessibleGroups.every(g=>expandedGroups[g.id]);
function toggleAllGroups(){const next=!allGroupsExpanded;if(sidebarCollapsed&&next){setSidebarCollapsed(false);try{localStorage.setItem('clinic.sidebar.collapsed','false')}catch{}}setExpandedGroups(Object.fromEntries(accessibleGroups.map(g=>[g.id,next])));}
async function init(){try{setEnvironment(await api('environment'));const reset=new URLSearchParams(window.location.hash.slice(1)).get('reset')||new URLSearchParams(window.location.search).get('reset');if(reset){setResetToken(reset);history.replaceState(null,'',window.location.pathname);setLoading(false);return;}if(new URLSearchParams(window.location.search).get('demo')==='1')await api('demo',{});try{const me=await api('me');setSession(me);setTab('dashboard');return}catch{}const s=await api('setup');setSetup(s.needed);setEnvironment(v=>({...v,tokenRequired:s.tokenRequired}));if(!s.needed){const me=await api('me');setSession(me);setTab('dashboard');}}catch{}finally{setLoading(false)}}
useEffect(()=>{init()},[]);
async function startDemo(role='owner'){setHelpOpen(false);setProfileId(null);setRecords({tab:null,rows:[]});setBusy(true);setError('');try{await api('demo',{role});const me=await api('me');setSession(me);setTab('dashboard');setForm({});setNotice('الديمو يستخدم بيانات وهمية منفصلة عن قاعدة المجمع')}catch(e){setError(e.message)}finally{setBusy(false)}}
async function refresh(){try{if(tab==='dashboard'){setRecords({tab,user:session?.user.id,rows:[]});return;}if(!session||!can(tab,'view')){setRecords({tab,rows:[]});return}const nextRows=await api(tab);if(tab==='appointments'||tab==='appointments/waiting')setStaff(await api('appointments/staff'));else if(tab==='tasks'||tab==='tasks/recurring')setStaff(await api('tasks/staff'));else if(tab==='finance/rates')setStaff(await api('finance/staff'));else if(tab==='quality/incidents')setStaff(await api('quality/incidents/staff'));if(tab==='equipment'&&can('purchasing/vendors','view'))setVendors(await api('purchasing/vendors'));else setVendors([]);if(can('patients','view'))setPatients(await api('patients'));if(can('roles','view'))setRoles(await api('roles'));setRecords({tab,user:session.user.id,rows:nextRows});}catch(e){setError(e.message)}}
useEffect(()=>{setProfileId(null);setFollowup(null);setForm({});setShowForm(false);setPage(1);setSort({key:'id',direction:1});setError('');setSearch('');refresh()},[tab,session]);
function openWorkspace(path,create=false){if(!can(path,'view'))return;setPendingCreate(create&&can(path,'create')?{path,user:session.user.id}:null);setTab(path);setMobileNav(false);setNavSearch('');window.scrollTo({top:0,behavior:'smooth'});}
