async function submit(e){e.preventDefault();setBusy(true);setError('');setNotice('');try{if(tab==='appointments'&&!form.id){const request_id=form.request_id||crypto.randomUUID();setForm(previous=>({...previous,request_id}));const result=await api('appointments/book',{...form,request_id});setHighlightAppointment(result.appointment_id);setPage(1);setForm({});setNotice('تم حفظ المريض والموعد بنجاح');setShowForm(false);await refresh();return;}await api(tab,tab==='clinical/templates'?{...form,defaults:JSON.stringify(form.structured||{})}:form);setForm({});setNotice('تم الحفظ بنجاح');setShowForm(false);await refresh()}catch(e){setError(e.message);if(e.duplicates)setForm({...form,confirmDuplicate:true})}finally{setBusy(false)}}
async function exportCurrent(format='csv'){setError('');try{let blob;if(format==='csv'){const {csv}=await api('reports/export',{path:tab});blob=new Blob([csv],{type:'text/csv;charset=utf-8'});}else{const response=await fetch('/api/reports/export',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path:tab,format})});if(!response.ok){const result=await response.json();throw Error(result.error)}blob=await response.blob();}const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=tab.replaceAll('/','-')+'.'+format;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}catch(e){setError(e.message)}}
function downloadProgram(r){const url=URL.createObjectURL(new Blob([programText(r)],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='home-program-'+r.id+'.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
