function field(key,title,type='text',required=true){if(tab==='quality/incidents'&&['description','corrective','preventive','closure_evidence'].includes(key))return <label className="wide" key={key}>{t(title)}<textarea required={required} rows={3} value={form[key]??''} onChange={e=>setForm({...form,[key]:e.target.value})}/></label>;if(key==='service'&&['appointments','finance'].includes(tab)&&!form.id)return <ServicePricePicker key={key} api={api} form={form} setForm={setForm} invoice={tab==='finance'}/>;return <label key={key}>{t(title)}<input type={type} required={required} value={form[key]??''} onChange={e=>setForm({...form,[key]:e.target.value})}/></label>}
function select(key,title,options,required=true){return <label>{t(title)}<select aria-label={t(title)} required={required} value={form[key]??''} onChange={e=>setForm({...form,[key]:e.target.value})}><option value="">{t("اختر")}</option>{options.map(([v,n])=><option key={v} value={v}>{['gender','source','kind','priority','method','status','active'].includes(key)?t(n):n}</option>)}</select></label>}
