function value(r,key){if(key==='remaining')return tab==='equipment'?Number(r.capacity)-Number(r.used):Number(r.amount)-Number(r.paid);if(key==='permissionCount')return r.permissions?.length||0;return r[key]??'';}
function cell(r,key){const v=value(r,key);if(key==='measurements'){const measures=JSON.parse(v||'[]');return measures.length?<div>{measures.map((m,i)=><p key={i}>{m.name}: {m.baseline??'—'} ← {m.value} {m.unit}{t("، التغير: ")}{m.change??'—'}</p>)}</div>:'—';}if(key==='escalated')return v?'نعم':'لا';if(key==='owner'&&r.owner_name)return r.owner_name;if(key==='approved')return <span className={'statusbadge '+(v?'good':'neutral')}>{v?t("معتمد"):t("مسودة")}</span>;if(key==='active')return <span className={'statusbadge '+(v?'good':'neutral')}>{v?t("نشط"):t("غير نشط")}</span>;if(key==='status'||key==='priority')return <span className={'statusbadge '+(['Completed','Confirmed'].includes(v)?'good':['Critical','Cancelled','No show'].includes(v)?'bad':'neutral')}>{language==='en'?v:(translations[v]||v)}</span>;if(key==='role')return roles.find(x=>x.id===v)?.name||v;if(key==='content')return <details><summary>{t("عرض التوثيق")}</summary><p className="clinicaltext">{v}</p>{r.structured&&<dl>{Object.entries(JSON.parse(r.structured)).map(([k,val])=><div key={k}><dt>{t({symptoms:'الأعراض',findings:'الفحص',pain:'الألم / 10',red_flag:'العلامات التحذيرية',flag_action:'الإجراء',goals:'الأهداف',interventions:'التدخلات',frequency:'التكرار',duration:'المدة',review:'إعادة التقييم',equipment:'الأجهزة',items:'المستهلكات',equipment_id:'رقم الجهاز',equipment_quantity:'استخدامات الجهاز',item_id:'رقم الصنف',item_quantity:'كمية المستهلك',outcome:'نتيجة العلاج',discharge_reason:'سبب الخروج',recommendations:'التوصيات',exercises:'التمارين',instructions:'التعليمات',minutes:'مدة الجلسة',specialty:'التخصص'}[k]||k)}</dt><dd>{val==='None'?t("لم تُرصد"):val==='Present'?t("تستلزم إجراء"):Array.isArray(val)?val.map(x=>x.name?x.dose?x.name+' — '+x.dose+'، '+x.frequency+'، '+x.instructions+(x.url?' — '+x.url:''):x.name+': '+x.value+' '+x.unit:'رقم '+x.id+' × '+x.quantity).join('، '):String(val)}</dd></div>)}</dl>}</details>;if(['amount','paid','remaining'].includes(key))return <bdi className="moneyvalue">{Number(v).toLocaleString(language==='en'?'en-GB':'ar-OM',{minimumFractionDigits:3,maximumFractionDigits:3})}</bdi>;if(['start','due','time'].includes(key))return <span className="datecell">{String(v).replace('T',' ')||'—'}</span>;return (language==='en'?String(v):translations[v]||String(v))||'—';}
const filteredRows=rows.filter(r=>search.startsWith('#')?String(r.id)===search.slice(1):JSON.stringify(r).toLowerCase().includes(search.toLowerCase())).sort((a,b)=>{if(tab==='appointments'&&highlightAppointment){if(a.id===highlightAppointment)return -1;if(b.id===highlightAppointment)return 1;}const x=value(a,sort.key),y=value(b,sort.key);return (typeof x==='number'&&typeof y==='number'?x-y:String(x).localeCompare(String(y),'ar',{numeric:true}))*sort.direction;});
